package com.chishakaychisha.spendwise.transaction; import java.util.*; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/transactions") @CrossOrigin public class TransactionController { private final TransactionRepository repo; TransactionController(TransactionRepository r){repo=r;} @GetMapping public List<Transaction> all(){return repo.findAll();} @PostMapping public Transaction create(@Valid @RequestBody Transaction t){return repo.save(t);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} }
